  res.locals.sourceAccount = await BankAccount.findOne({ where: { iban: req.body.sourceIban } });
  if (!res.locals.sourceAccount) return res.status(404).json({ error: 'Account not found' });
  next();
};

app.post('/api/transfers/wire', sessionAuth, resolveSourceAccount, async (req, res) => {
  const transfer = await wireTransferService.execute({
    fromAccount: res.locals.sourceAccount,
    toIban: req.body.destinationIban,
    amount: req.body.amount
  });
  res.json({ status: 'completed', transferId: transfer.id });
});

corrected_code:
const resolveSourceAccount = async (req, res, next) => {
  res.locals.sourceAccount = await BankAccount.findOne({
    where: { iban: req.body.sourceIban, userId: req.session.userId }
  });
  if (!res.locals.sourceAccount) return res.status(403).json({ error: 'Unauthorized: source account not owned by user' });
  next();
};

app.post('/api/transfers/wire', sessionAuth, resolveSourceAccount, async (req, res) => {
  const transfer = await wireTransferService.execute({
    fromAccount: res.locals.sourceAccount,
    toIban: req.body.destinationIban,
    amount: req.body.amount
  });
  res.json({ status: 'completed', transferId: transfer.id });
});
